"""Curated DE/EN explanations, matched by register address, never by PDF P-code alone.

The referenced page numbers are PDF pages (1-based). No defaults, ranges or
device settings are changed. Protocol-only meanings explicitly retain gaps.
Run after extracting manuals to artifacts/parameter-manual-review.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CATALOG = ROOT / "custom_components/r290_heatpump/frontend/register-catalog.json"
records = {r["code"]: r for r in json.loads(CATALOG.read_text(encoding="utf-8"))["records"] if r["section"] == 4}
protocol = json.loads((ROOT / "artifacts/parameter-manual-review/Modbus_protocol_V1.2.9.json").read_text(encoding="utf-8"))
help_text = {}


def add(number, de, en, *, pages=None, source=None, level="documented"):
    code = f"P{number:03d}"
    record = records[code]
    assert record["address"] == 0x100 + number
    if source is None:
        matches = [p["page"] for p in protocol["pages"] if record["hex"].lower() in p["text"].lower()]
        source = "Modbus_protocol_V1.2.9.pdf" if matches else "Technisches Handbuch.pdf"
        pages = matches or [181]
    help_text[code] = {"address": record["address"], "de": de, "en": en,
                       "level": level, "sources": [{"file": source, "pages": pages}]}


add(11, "Abschaltschwelle des Hochdruckschutzes. Der Registerwert ist als Temperatur angegeben, nicht in bar; das Servicehandbuch beschreibt die Hochdruck-Sättigungstemperatur als Vergleichsgröße.", "High-pressure protection shutdown threshold. The register is expressed as temperature, not bar; the service manual identifies the high-pressure saturation temperature as the comparison value.", source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf", pages=[52,83])
add(13, "Schutzschwelle auf der Niederdruckseite des Kältekreises. Angegeben als Temperatur, nicht als Druck in bar. Bei Unterschreitung kann die Geräteschutzregelung den Verdichter abschalten.", "Protection threshold on the low-pressure side of the refrigerant circuit. Expressed as temperature, not pressure in bar. Falling below it can cause the device protection to stop the compressor.", source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf", pages=[52,83])
for n,side,side_en in [(12,'Hochdruckseite','high-pressure side'),(14,'Niederdruckseite','low-pressure side')]:
    add(n,f"Temperaturschwelle zur Begrenzung der Verdichterfrequenz auf der {side}. Sie dient der Leistungsreduzierung vor einer Schutzabschaltung; sie ist keine Frequenzvorgabe in Hz. Der genaue Abstand zur Abschaltschwelle ist firmwareabhängig.",f"Temperature threshold for limiting compressor frequency on the {side_en}. It reduces output before protection shutdown; it is not a frequency setpoint in Hz. The exact margin to the shutdown threshold depends on firmware.")
add(15,"Obere Heißgas-/Verdichteraustrittstemperatur für die Schutzabschaltung. Bezieht sich auf den Kältekreis, nicht auf den Heizungs-Vorlauf.","Upper discharge-gas/compressor-outlet temperature for protection shutdown. Refers to the refrigerant circuit, not the heating-water supply.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[52,83])
add(16,"Heißgastemperaturschwelle für die Begrenzung der Verdichterfrequenz. Die Einheit ist °C; der Parameter begrenzt nicht direkt die Frequenz in Hz.","Discharge-gas temperature threshold for limiting compressor frequency. Its unit is °C; it does not directly specify a frequency limit in Hz.")
for n,mode,en_mode,action,en_action in [(17,'Kühlen','cooling','Erhöhen','increasing'),(18,'Kühlen','cooling','Absenken','reducing'),(19,'Heizen','heating','Absenken','reducing'),(20,'Heizen','heating','Erhöhen','increasing')]:
    add(n,f"Temperaturkriterium zum {action} der Lüfterdrehzahl im Modus {mode}. Kein Drehzahl-Sollwert und keine Zeitverzögerung: Das Register ist in °C dokumentiert. Die genaue Vergleichstemperatur ist in der Registertabelle nicht erläutert.",f"Temperature criterion for {en_action} fan speed during {en_mode}. This is neither a speed setpoint nor a time delay: the register is documented in °C. The register table does not specify the exact comparison temperature.",level="partial")
add(21,"Untere Außentemperaturgrenze für den Start der Wärmepumpe. Unterhalb dieser Grenze kann der Verdichterstart gesperrt werden; dies ist nicht die Einschaltschwelle der Frostschutz-Umwälzung.","Lower outdoor-temperature limit for starting the heat pump. Below it, compressor start may be inhibited; this is not the threshold for frost-protection circulation.")
add(22,"Außentemperaturkriterium für die Freigabe der elektrischen Zusatzheizung. Protokoll 0x0116 und Servicehandbuch nennen diese Funktion; die abweichende Excel-Notiz zu Startsperre/Abtauung passt dazu nicht. Freigabe ist noch kein dauerhafter Heizbefehl.","Outdoor-temperature criterion for enabling auxiliary electric heating. Protocol address 0x0116 and the service manual name this function; the conflicting spreadsheet note about start inhibition/defrost does not match. Enablement is not a continuous heating command.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[45,47,83],level="conflict")
for n,location,en_location in [(24,'Rücklauf','return-water'),(25,'Vorlauf','outlet-water'),(98,'Warmwasserspeicher','DHW-tank')]:
    add(n,f"Manueller Temperatur-Korrekturwert für den {location}fühler. Korrigiert den von der Gerätesteuerung verwendeten Messwert; verändert nicht unmittelbar den gewünschten Sollwert. Nur eine nachgewiesene Fühlerabweichung damit ausgleichen.",f"Manual temperature correction for the {en_location} sensor. Adjusts the reading used by the device controller, rather than directly changing the desired setpoint. Use it only to compensate a verified sensor error.")
for n,mode,en_mode in [(26,'Heiz-/Kühlbetrieb','heating/cooling'),(27,'Fußbodenheizbetrieb','floor heating')]:
    add(n,f"Wiedereinschalt-Hysterese im {mode}. Sie bestimmt den Abstand zur Solltemperatur, ab dem erneut Wärme- bzw. Kühlbedarf entsteht. Ein größerer Abstand erlaubt größere Temperaturschwankungen. Die tatsächlich verwendete Regeltemperatur hängt von der Gerätekonfiguration ab; dies ist nicht die Vorlauf-Rücklauf-Spreizung P099.",f"Restart hysteresis for {en_mode}. Defines the distance from the setpoint at which heating or cooling demand returns. A larger distance permits larger temperature swings. The control temperature depends on device configuration; this is not the supply/return difference P099.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[41,42,43,83])
add(29,"Dauer eines Frostschutz-Umwälzlaufs. Das Protokoll nennt einen Lauf je zehn Minuten; der Eintritt in den Frostschutz hängt zusätzlich von Temperaturbedingungen ab. Dieser Wert beschreibt die Laufdauer, nicht die Verdichterlaufzeit und nicht das Intervall P175.","Duration of one frost-protection circulation run. The protocol specifies one run every ten minutes; entering frost protection also depends on temperature conditions. This value is the run duration, not compressor runtime or interval P175.")
add(31,"Kumulierte Betriebszeit als Kriterium für den Beginn einer Abtauung. Weitere Abtaubedingungen bleiben erforderlich. Die Dokumentation enthält widersprüchliche Einheiten; nicht als Spulentemperatur interpretieren.","Accumulated operating time used as a criterion for starting defrost. Other defrost conditions still apply. Documentation contains conflicting units; do not interpret it as a coil-temperature setting.",level="conflict")
add(32,"Temperaturschwelle des Außenwärmetauschers für den Eintritt in die Abtauung. Die Auswertung erfolgt zusammen mit den übrigen Bedingungen des gewählten Abtaumodus.","Outdoor-coil temperature threshold for entering defrost. Evaluated together with the other conditions of the selected defrost mode.")
for n in (33,34):
    add(n,f"Abtau-Temperaturdifferenz {n-32}: eines der Eintrittskriterien der Abtauregelung. Die Registertabelle benennt die beteiligten Fühler und die Verknüpfung der beiden Differenzen nicht eindeutig; daher keine konkrete Schaltformel ableiten.",f"Defrost temperature difference {n-32}: one of the defrost entry criteria. The register table does not clearly identify the sensor pair or how the two differences are combined; no exact switching formula can be derived.",level="partial")
add(35,"Zeitliche Obergrenze eines Abtauvorgangs. Die reguläre Beendigung kann vorher durch die Austrittsbedingungen erfolgen. Es handelt sich um eine Zeit, auch wenn einzelne Tabellen fälschlich °C angeben.","Maximum duration of a defrost operation. Normal exit conditions can end it sooner. This is a time value despite some tables incorrectly labelling it °C.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[84])
add(36,"Temperatur des Außenwärmetauschers für das Beenden der Abtauung. Keine Lüfter-Solltemperatur; weitere Mindestzeit- und Schutzbedingungen können gelten.","Outdoor-coil temperature used to end defrost. Not a fan temperature setpoint; minimum-time and protection conditions may also apply.")
add(38,"Konstante für die anfängliche Öffnung des elektronischen Haupt-Expansionsventils beim Heizen. Beeinflusst die Startberechnung im Kältekreis; ist keine Vorgabe für das hydraulische Dreiwegeventil.","Constant for the initial main electronic expansion-valve opening during heating. Affects the refrigerant-circuit startup calculation; it is not a command for the hydraulic three-way valve.")
for n,mode,en_mode in [(40,'Kühlen','cooling'),(42,'Heizen','heating')]:
    add(n,f"Korrektur der Soll-Überhitzung im Modus {mode}. Die Überhitzung beschreibt Kältemitteltemperatur gegenüber Sättigungstemperatur; sie ist nicht die Wasserspreizung. Verändert das Regelziel des elektronischen Expansionsventils.",f"Correction of target refrigerant superheat during {en_mode}. Superheat is refrigerant temperature relative to saturation temperature, not the water temperature difference. Adjusts the electronic expansion valve's control target.")
add(41,"Temperaturkorrektur der Hochdruck-Schutz- und Frequenzbegrenzungsschwellen beim Heizen. Wirkt auf die Kältekreis-Schutzregelung und nicht auf die Heizkurve.","Temperature correction for high-pressure protection and frequency-limiting thresholds during heating. Affects refrigerant-circuit protection, not the heating curve.")
add(45,"Kommunikationsadresse des Geräts. Eine Änderung kann die bestehende Modbus-Verbindung unterbrechen. Die Adresse muss zur Buskonfiguration passen und darf nicht doppelt vergeben sein.","Device communication address. Changing it can interrupt the existing Modbus connection. It must match the bus configuration and must not duplicate another address.")
add(46,"Schalthysterese für das Flüssigkeitseinspritz-Magnetventil im Kältekreis. Die Differenz trennt dessen Ein- und Ausschaltbedingungen; sie steuert keine Heizungs-Umwälzpumpe.","Switching hysteresis for the refrigerant liquid-injection solenoid valve. Separates its on/off conditions; it does not control a heating circulation pump.")
add(47,"Konstante der EVI-Sollüberhitzung für die Kältemitteleinspritzung. Die genaue Berechnungsformel wird in der Registertabelle nicht beschrieben.","EVI target-superheat constant for refrigerant injection. The register table does not describe the exact calculation formula.",level="partial")
add(49,"Prozentvorgabe für die Verdichter-Betriebsfrequenz im Warmwasserbetrieb. Die Bezugsfrequenz ist in der Registertabelle nicht näher definiert. Nicht mit dem Anteil freigegebener Kaskadengeräte P168 verwechseln.","Percentage setting for compressor operating frequency during DHW production. The reference frequency is not further defined in the register table. Do not confuse it with the permitted cascade-unit ratio P168.",level="partial")
for n,mode,mode_en,symbol,formula in [(50,'Kühlen','cooling','A','Y = 9X/5 + A'),(54,'Heizen','heating','B','Y = B − X'),(60,'Warmwasser','DHW','B','Y = B − X')]:
    add(n,f"Konstante {symbol} der Sollfrequenzberechnung für {mode}: {formula}. Eine Änderung verschiebt die berechnete Frequenz. Die Registertabelle definiert die Eingangsgröße X nicht eindeutig; keine Außentemperaturzuordnung voraussetzen.",f"Constant {symbol} in the target-frequency calculation for {mode_en}: {formula}. Changing it shifts the calculated frequency. The register table does not unambiguously define input X; do not assume it is outdoor temperature.",level="partial")
for n,mode,mode_en,limit,limit_en in [(51,'Kühlen','cooling','Untere','Lower'),(52,'Kühlen','cooling','Obere','Upper'),(53,'Kühlen','cooling','Untere','Lower'),(55,'Heizen','heating','Obere','Upper'),(56,'Heizen','heating','Untere','Lower'),(61,'Warmwasser','DHW','Obere','Upper'),(62,'Warmwasser','DHW','Untere','Lower')]:
    add(n,f"{limit} Grenze der Verdichterfrequenz im Modus {mode}. Begrenzt die Modulation in Hz, fordert aber keinen Start an. Weitere Betriebs- und Schutzgrenzen können die tatsächlich gefahrene Frequenz einschränken.",f"{limit_en} compressor-frequency limit during {mode_en}. Constrains modulation in Hz but does not request a start. Other operating and protection limits can further restrict actual frequency.")
for n in (*range(57,60),*range(63,66)):
    stage=(n-57)%6+1 if n<60 else n-62
    zone=['über 0 °C','von −10 bis unter 0 °C','unter −10 °C'][stage-1]
    zone_en=['above 0 °C','from −10 to below 0 °C','below −10 °C'][stage-1]
    mode,en_mode=('Heizen','heating') if n<60 else ('Warmwasser','DHW')
    add(n,f"Mindest-Verdichterfrequenz Stufe {stage} für {mode}. Das Vergleichs-Servicehandbuch ordnet diese Stufe Außentemperaturen {zone} zu. Die genaue Stufenauswahl und Grenzfallbehandlung der installierten Firmware sind damit nicht bestätigt.",f"Stage {stage} minimum compressor frequency for {en_mode}. The comparison service manual assigns this stage to outdoor temperatures {zone_en}. This does not verify the exact stage selection or boundary handling in the installed firmware.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[84],level="partial")
for n,de,en in [(66,'Startvorgabe','Initial setting'),(67,'Untere Grenze beim Heizen','Lower limit during heating'),(68,'Obere Grenze beim Heizen','Upper limit during heating'),(69,'Untere Grenze beim Kühlen','Lower limit during cooling'),(70,'Obere Grenze beim Kühlen','Upper limit during cooling'),(89,'Obere Grenze im Leisemodus','Upper limit in quiet mode'),(173,'Untere Zielfrequenz beim Heizen','Lower target frequency during heating')]:
    add(n,f"{de} für die DC-Lüfterfrequenz. Der Wert betrifft den Außenlüfter, nicht Verdichter oder Wasserpumpe. Die Zuordnung von Hz zu realer Drehzahl hängt vom Lüfter-/Treiberaufbau ab.",f"{en} for DC fan frequency. Applies to the outdoor fan, not the compressor or water pump. Conversion from Hz to actual speed depends on the fan/driver design.")
for n,de,en in [(71,'Zuschalten','enabling'),(72,'Abschalten','disabling')]:
    add(n,f"Verdichterfrequenz als Kriterium zum {de} der EVI-/Enthalpieerhöhung. Kein direkter Frequenzbefehl; zusätzliche Temperatur- und Zeitbedingungen können gelten.",f"Compressor-frequency criterion for {en} EVI/enhanced vapour injection. Not a direct frequency command; additional temperature and time conditions may apply.")
for n in range(73,76):
    add(n,f"Anfangsöffnung {n-72} des elektronischen Haupt-Expansionsventils beim Kühlen, in Ventilschritten. Die Auswahl zwischen den drei Startöffnungen ist nicht erläutert. Betrifft den Kältekreis und nicht ein Wasser-Umschaltventil.",f"Initial opening {n-72} of the main electronic expansion valve during cooling, in valve steps. Selection between the three startup openings is not explained. Applies to the refrigerant circuit, not a water diverter valve.",level="partial")
for n,valve,valve_en,action,action_en in [(76,'Hauptventils beim Kühlen','main valve during cooling','Untere','Lower'),(77,'Hauptventils beim Heizen','main valve during heating','Untere','Lower'),(78,'Hauptventils','main valve','Obere','Upper'),(82,'Hilfsventils','auxiliary valve','Obere','Upper'),(83,'Hilfsventils','auxiliary valve','Untere','Lower')]:
    add(n,f"{action} Öffnungsgrenze des elektronischen {valve}, in Ventilschritten. Begrenzt die Kältemittel-Dosierung. Keine Prozentvorgabe für die Zusatzpumpe oder das Dreiwegeventil.",f"{action_en} opening limit of the electronic {valve}, in valve steps. Constrains refrigerant metering. Not a percentage setting for the auxiliary pump or three-way valve.")
for n,letter in [(79,'c'),(80,'a'),(81,'b'),(85,'c'),(86,'a'),(87,'b')]:
    valve,en_valve=('Hauptventils','main valve') if n<82 else ('Hilfsventils','auxiliary valve')
    add(n,f"Koeffizient {letter} der Berechnung für die Anfangsöffnung des elektronischen {valve}. Die Registertabelle nennt keine vollständige Formel; der Wert ist kein direkt anfahrbarer Öffnungsgrad.",f"Coefficient {letter} used to calculate the initial opening of the electronic {en_valve}. The register table gives no complete formula; this is not a direct opening command.",level="partial")
for n,valve,en_valve in [(84,'Haupt-Expansionsventils','main expansion valve'),(94,'Hilfs-Expansionsventils','auxiliary expansion valve')]:
    add(n,f"Zeitabstand zwischen Regelanpassungen des elektronischen {valve}. Ein kleinerer Wert ermöglicht häufigere Anpassungen im Kältekreis; dies ist kein Pumpenintervall.",f"Time between control adjustments of the electronic {en_valve}. A smaller value permits more frequent refrigerant-circuit adjustments; this is not a pump interval.")
add(88,"Maximale Verdichterfrequenz bei aktiviertem Leisemodus. Begrenzt die verfügbare Leistung in diesem Modus; erzwingt weder diese Frequenz noch einen Verdichterstart.","Maximum compressor frequency when quiet mode is active. Limits available output in that mode; does not force this frequency or start the compressor.")
for n,de,en in [(90,'Außentemperaturkriterium','Outdoor-temperature criterion'),(91,'Sperrzeit','Inhibit time'),(92,'Temperaturdifferenzkriterium','Temperature-difference criterion'),(93,'Erforderliche kontinuierliche Verdichterlaufzeit','Required continuous compressor runtime')]:
    add(n,f"{de} für den Eintritt in den EVI-Betrieb (Kältemitteleinspritzung). Gehört zu einer Gruppe von Freigabebedingungen; allein aus diesem Register lässt sich keine vollständige Ein-/Ausschaltregel ableiten.",f"{en} for entering EVI operation (refrigerant injection). Part of a group of enabling conditions; this register alone does not define a complete on/off rule.",level="partial")
add(96,"Hysterese für das Nachladen des Warmwasserspeichers. Das Servicehandbuch beschreibt den erneuten Start unter Warmwassersollwert minus P096; weitere Freigaben bleiben erforderlich. Größere Werte erlauben stärkere Speicherabkühlung vor dem Nachladen.","Hysteresis for reheating the DHW tank. The service manual describes restarting below the DHW setpoint minus P096; other enabling conditions still apply. Larger values permit more tank cooling before reheating.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[42,84])
add(97,"Automatische Korrektur der Warmwasserspeichertemperatur. Achtung: Protokoll/Excel nennen 0 = aktiv, 1 = aus; das Hainzel-Handbuch nennt die umgekehrte Belegung. Die Zuordnung ist für die installierte Firmware nicht bestätigt; nicht als gesicherte Umschaltanweisung verwenden.","Automatic DHW-tank temperature compensation. Caution: protocol/spreadsheet say 0 = enabled, 1 = disabled; the Hainzel manual gives the opposite mapping. The mapping is not verified for the installed firmware and must not be treated as a confirmed switching instruction.",source="Solareast/Hainzel - Engineering Manual-R290 V1-0_DE.pdf",pages=[151],level="conflict")
add(99,"Zielspreizung zwischen Wasseraustritt und Wassereintritt für die interne drehzahlgeregelte Umwälzpumpe. Größere Spreizung bedeutet bei gleicher Wärmeleistung weniger Durchfluss. Mindestdurchfluss und Pumpengrenzen bleiben vorrangig. Dieser Parameter stellt nicht die separate Zusatzpumpe ein.","Target difference between water outlet and inlet for the internal variable-speed circulation pump. At the same heat output, a larger difference corresponds to lower flow. Minimum flow and pump limits still take priority. This parameter does not configure the separate auxiliary pump.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[41,84])
add(100,"Untere PWM-Ansteuerungsgrenze der internen Umwälzpumpe während der Drehzahlregelung. Begrenzt die Absenkung, garantiert aber keinen bestimmten Durchfluss. Die separate Zusatzpumpe hat eigene Grenzen.","Lower PWM control limit for the internal circulation pump during speed regulation. Limits reduction but does not guarantee a particular flow. The separate auxiliary pump has its own limits.")
add(103,"Mindestlaufzeit vor regulärer temperaturbedingter Abschaltung oder Wechsel des kombinierten Betriebsmodus. Keine generelle Überbrückung von Schutzabschaltungen. Das Vergleichs-Servicehandbuch beschreibt 0 als ohne diese Begrenzung.","Minimum runtime before normal temperature-related shutdown or combined-mode switching. Does not generally override protective shutdowns. The comparison service manual describes 0 as removing this restriction.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[41,85])
add(104,"Prozentuale Betriebsfrequenzvorgabe während eines Moduswechsels. Betrifft den Verdichter; kein Anteil der Kaskadengeräte. Die Bezugsfrequenz ist nicht genauer erläutert.","Percentage operating-frequency setting during a mode change. Applies to the compressor, not the proportion of cascade units. The reference frequency is not explained further.",level="partial")
for n,mode,en_mode,limit,en_limit in [(105,'Kühlbetrieb','cooling','Untere','Lower'),(106,'Heizbetrieb','heating','Obere','Upper'),(107,'Warmwasserbetrieb','DHW','Obere','Upper')]:
    add(n,f"{limit} Außentemperaturgrenze für den Start im {mode}. Begrenzt den zulässigen Einsatzbereich; ist keine Wasser-Solltemperatur und keine Heizkurvenstützstelle.",f"{en_limit} outdoor-temperature limit for starting {en_mode}. Restricts the permitted operating envelope; it is neither a water-temperature setpoint nor a heating-curve point.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[41,42,85])
for n,mode,en_mode,limit,en_limit in [(108,'Warmwasser','DHW','Obere','Upper'),(109,'Warmwasser','DHW','Untere','Lower'),(110,'Heizen','heating','Obere','Upper'),(111,'Heizen','heating','Untere','Lower'),(112,'Kühlen','cooling','Obere','Upper'),(113,'Kühlen','cooling','Untere','Lower')]:
    add(n,f"{limit} Grenze des einstellbaren Wassersollwerts für {mode}. Beschränkt den zulässigen Sollwertbereich; setzt nicht selbst den aktuellen Sollwert und entspricht keiner garantierten Isttemperatur.",f"{en_limit} bound of the adjustable water-temperature setpoint for {en_mode}. Restricts the permitted setpoint range; does not itself set the current target or guarantee an actual temperature.")
add(114,"Anzahl der Verdichter innerhalb eines Geräts: 1 oder 2. Nicht die Anzahl der parallel angeschlossenen Wärmepumpen in der Kaskade.","Number of compressors inside one unit: 1 or 2. Not the number of parallel heat pumps in the cascade.")
add(117,"Außentemperaturschwelle für die Frostschutzlogik. Kann Umwälzung auch bei ausgeschaltetem Verdichter auslösen. Zusätzliche Wasser-/Speichertemperaturbedingungen bestimmen weitergehende Schutzmaßnahmen.","Outdoor-temperature threshold for frost protection. Can trigger circulation even with the compressor off. Additional water/tank-temperature conditions determine further protective actions.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[49,50])
add(118,"Wassertemperaturschwelle der Frostschutzlogik. Zusammen mit den übrigen Bedingungen kann daraus nicht nur Umwälzung, sondern auch ein Heizstart zum Frostschutz entstehen. Nicht mit dem Gefrierpunkt des eingefüllten Mediums gleichsetzen.","Water-temperature threshold for frost protection. Together with other conditions it can trigger protective heating as well as circulation. It is not the freezing point of the fluid in the circuit.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[49,50])
for n in range(121,133):
    heating=n<127;offset=n-(121 if heating else 127);stage=offset//2+1;low=offset%2==0
    add(n,f"{'Untere' if low else 'Obere'} Grenze des gesperrten Frequenzbandes {stage} beim {'Heizen' if heating else 'Kühlen'}. Gehört zur Aussparung bestimmter Verdichterfrequenzen und nicht zur normalen Mindest-/Maximalfrequenz. Wie die Firmware das Band überfährt, ist nicht beschrieben.",f"{'Lower' if low else 'Upper'} boundary of blocked frequency band {stage} during {'heating' if heating else 'cooling'}. Defines excluded compressor frequencies rather than the normal minimum/maximum frequency. How firmware crosses the band is not described.",level="partial")
add(134,"Untere Durchflussschwelle der Geräteschutzüberwachung. Unterschreitung kann einen Wasserflussfehler und Abschaltung auslösen. Dies ist eine Schutzschwelle, nicht automatisch der für effizienten oder sicheren Dauerbetrieb empfohlene Mindestdurchfluss.","Lower flow threshold of device protection. Falling below it can cause a water-flow fault and shutdown. This is a protection threshold, not automatically the recommended minimum flow for efficient or safe continuous operation.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[51,85])
add(135,"Temperaturdifferenz für den Eintritt in die Antikondensationsfunktion. Das Servicehandbuch nennt eine Abhängigkeit von P120. Fühlerpaar und vollständige Schaltbedingungen sind nicht eindeutig erläutert.","Temperature difference for entering anti-condensation operation. The service manual states a dependency on P120. The sensor pair and complete switching conditions are not clearly explained.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[85],level="partial")
add(136,"Außentemperaturkriterium für das Öffnen des Drossel-Bypassventils im Kältekreis. Nicht das hydraulische Umschaltventil zwischen Warmwasser und Heizung.","Outdoor-temperature criterion for opening the refrigerant throttle bypass valve. Not the hydraulic diverter between DHW and heating.")
add(137,"Zeitverzögerung des Drossel-Bypassventils in Bezug auf den Verdichter. Das Protokoll nennt Sekunden, erläutert aber die genaue Start-/Stoppsequenz nicht.","Throttle-bypass-valve delay relative to the compressor. The protocol specifies seconds but does not explain the exact start/stop sequence.",level="partial")
add(138,"Verdichterfrequenzvorgabe während der Abtauung. Gilt für den Kältekreis; die Umwälzpumpe hat eine getrennte Ansteuerung. Temperaturabhängige Abtaustufen können zusätzlich wirksam sein.","Compressor-frequency setting during defrost. Applies to the refrigerant circuit; the circulation pump is controlled separately. Temperature-dependent defrost stages may also apply.")
add(141,"Zeitkriterium des taupunktbezogenen Abtaumodus. Nur im Zusammenhang mit dem gewählten Abtaumodus beurteilen; die vollständige Eintrittslogik ist nicht beschrieben.","Time criterion for the dew-point-based defrost mode. Interpret together with the selected defrost mode; the complete entry logic is not documented.",level="partial")
add(142,"Konstante der taupunktbezogenen Abtauregelung. Bedeutung der Konstante innerhalb der Berechnungsformel und genaue Skalierung sind in den vorliegenden Unterlagen nicht erläutert.","Constant for dew-point-based defrost control. Its role in the calculation formula and exact scaling are not explained in the available documents.",level="partial")
for n,de,en in [(143,'Wasser','Water'),(144,'Außen','Outdoor')]:
    add(n,f"{de}temperaturkriterium für den Eintritt in die Abtauung. Ein einzelner erfüllter Grenzwert bestätigt keinen Abtaustart; weitere Kriterien des gewählten Modus gelten.",f"{en}-temperature criterion for entering defrost. Meeting this one threshold does not confirm a defrost start; other criteria of the selected mode apply.")
add(145,"Frostschutzgrenze für die Wasseraustrittstemperatur. Gehört zum Geräteschutz und ist von Zieltemperatur sowie Zielspreizung getrennt zu betrachten.","Freeze-protection limit for outlet-water temperature. Part of device protection, separate from target temperature and target temperature difference.")
add(146,"Messbereichsvorgabe für die Durchflussrückmeldung der Pumpe, in L/min. Laut Servicehandbuch passend zum Pumpenmodell einstellen. Kein Ziel- oder Mindestdurchfluss.","Range setting for pump flow feedback, in L/min. The service manual says to match it to the pump model. Not a target or minimum flow setting.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[85])
add(148,"Temperaturgrenze des Frostschutzes im Kühlbetrieb. Wird in Abhängigkeit vom gewählten Frostschutzmodus P147 verwendet. Die Registertabelle allein bestätigt nicht, welcher Fühler der installierten Firmware maßgeblich ist.","Freeze-protection temperature limit during cooling. Used according to frost-protection mode P147. The register table alone does not confirm which sensor the installed firmware uses.",level="partial")
add(149,"Wasseraustrittstemperatur, ab der die Verdichterfrequenz begrenzt werden kann. Der Parameter ist in °C angegeben, obwohl der Name Frequenz enthält; kein maximaler Hz-Wert.","Outlet-water temperature at which compressor frequency may be limited. The parameter is expressed in °C despite its name mentioning frequency; it is not a maximum Hz value.")
for n,mode,en_mode in [(153,'Warmwasser','DHW'),(154,'Heizung','heating')]:
    add(n,f"Obere Temperaturvorgabe für den kombinierten Betrieb mit einer zusätzlichen Wärmequelle auf der Seite {mode}. Betrifft diese Kombination und nicht zwingend den normalen alleinigen Wärmepumpenbetrieb.",f"Upper temperature setting for combined operation with an additional heat source on the {en_mode} side. Applies to that combination, not necessarily normal heat-pump-only operation.")
add(155,"Auswahl eines Verdichtercodes, in den Unterlagen ausdrücklich als reservierte Funktion bezeichnet. Eine nutzbare Wirkung und passende Codes für dieses Gerät sind nicht dokumentiert.","Compressor-code selection, explicitly marked as a reserved function. A usable effect and suitable codes for this unit are not documented.",level="reserved")
add(157,"Temperaturdifferenz für die Reduzierung am elektronischen Hilfs-Expansionsventil. Welche Temperaturen verglichen werden und wie stark das Ventil reagiert, ist in der Registertabelle nicht angegeben.","Temperature difference used for reduction at the auxiliary electronic expansion valve. The register table does not specify the compared temperatures or the amount of valve response.",level="partial")
for n,term,en_term in [(159,'Konstante','Constant'),(160,'Koeffizient','Coefficient')]:
    add(n,f"{term} der temperaturabhängigen Begrenzung beim Heizen, zusammen mit der Freigabebedingung P158. Die vollständige Formel fehlt; der Wert darf nicht unmittelbar als Vorlaufsolltemperatur interpretiert werden.",f"{en_term} for temperature-dependent limiting during heating, associated with enabling condition P158. The complete formula is absent; do not interpret this value directly as a supply-temperature setpoint.",level="partial")
add(163,"Untergrenze der Pumpenregelung, aber widersprüchlich dokumentiert: Protokoll/Excel nennen eine prozentuale Rückmeldung, das Servicehandbuch einen Mindestdurchfluss in L/min. Funktion und Einheit müssen für diese Firmware bestätigt werden; nicht ungeprüft als Prozent oder L/min einstellen.","Lower limit in pump control, with conflicting documentation: protocol/spreadsheet describe percentage feedback, whereas the service manual describes minimum flow in L/min. Function and unit must be confirmed for this firmware; do not blindly configure it as percent or L/min.",source="Solareast/ARDEN-R290-Heat-Pump-Service-Manual-.pdf",pages=[41,86],level="conflict")
for n,mode,en_mode in [(168,'Warmwasserbetrieb','DHW mode'),(169,'Heiz-/Kühlbetrieb','heating/cooling mode')]:
    add(n,f"Begrenzt laut Kaskadenkapitel die Gesamtzahl der startenden Geräte im {mode}, sofern die entsprechende Kaskadenregelung über P164 aktiv ist. 100 % erlaubt alle Geräte; dies ist kein Verdichter-Leistungswert und keine Zuschaltverzögerung. Für die Zuschaltung sind auch P165 und P170 relevant. Bei zwei Geräten kann 50 % die verfügbare Anzahl auf ein Gerät begrenzen, statt das zweite nur später zu starten. Die Rundung bei Zwischenwerten wie 60 % oder 75 % und der genaue Erststartablauf sind nicht dokumentiert.",f"According to the cascade section, limits the total number of starting units in {en_mode} when the corresponding cascade control is enabled through P164. 100% permits all units; it is neither compressor output nor a staging delay. P165 and P170 also affect staging. With two units, 50% may limit availability to one unit rather than merely delay the second. Rounding at intermediate settings such as 60% or 75% and the exact initial-start sequence are not documented.",source="Technisches Handbuch.pdf",pages=[90,91],level="partial")
add(170,"Zeitparameter für das Zuschalten des nächsten Geräts bei aktiver Kaskadenregelung. Zusammen mit P164, der Zuschalt-Temperaturdifferenz P165 und der Geräteanzahlbegrenzung P168/P169 zu beurteilen. Das Handbuch bestätigt keine zwingende Mindestwartezeit zwischen den allerersten Verdichterstarts; der genaue Beginn bzw. Rücksetzpunkt dieses Zeitzyklus ist nicht beschrieben.","Time setting for staging the next unit when cascade control is enabled. Interpret together with P164, staging temperature difference P165 and unit-count limit P168/P169. The manual does not establish a mandatory minimum delay between the initial compressor starts; the exact start/reset point of this cycle is not described.",source="Technisches Handbuch.pdf",pages=[90,91],level="partial")
add(171,"Außentemperaturgrenze zum Ausblenden des Niederdruckschalters. Die englische Übersetzung nennt teilweise fälschlich Niederspannung. Welche Schutzprüfung bei welcher Vergleichsrichtung entfällt, ist nicht ausreichend belegt.","Outdoor-temperature threshold for masking the low-pressure switch. Some English labels incorrectly say low voltage. The precise masked protection check and comparison direction are not sufficiently documented.",level="partial")
add(172,"Konstante c für die Sollfrequenzberechnung des DC-Lüfters. Keine unmittelbar gemessene Drehzahl. Die vollständige Formel und ihre Eingangsgrößen sind nicht dokumentiert.","Constant c for the DC-fan target-frequency calculation. Not a directly measured speed. The complete formula and its inputs are not documented.",level="partial")
add(174,"Öffnung des elektronischen Haupt-Expansionsventils während der Abtauung, in Ventilschritten. Nicht die Stellung eines hydraulischen Dreiwege- oder Kugelventils.","Main electronic expansion-valve opening during defrost, in valve steps. Not the position of a hydraulic three-way or ball valve.",source="Technisches Handbuch.pdf",pages=[178])
add(175,"Intervallzyklus der Wasserpumpe bei temperaturbedingtem Stillstand des Geräts. Das technische Handbuch ordnet Register 0x01AF ausdrücklich diesem Pumpenintervall zu. Nicht mit der Laufdauer P029 oder der Kaskaden-Zuschaltverzögerung P170 verwechseln. Die Bedeutung von 0 und der exakte Wiedereinschaltablauf sind nicht erläutert.","Water-pump interval cycle while the unit is stopped at its target temperature. The technical manual explicitly assigns register 0x01AF to this pump interval. Do not confuse it with run duration P029 or cascade loading delay P170. The meaning of 0 and the exact restart sequence are not explained.",source="Technisches Handbuch.pdf",pages=[178],level="partial")
add(176,"Mindestdauer des Abtaubetriebs, in Sekunden. Kann das reguläre temperaturbedingte Abtauende verzögern; ist keine allgemeine Aufhebung von Schutzabschaltungen.","Minimum duration of defrost operation, in seconds. May delay normal temperature-based defrost completion; does not generally override protective shutdowns.",source="Technisches Handbuch.pdf",pages=[178])
add(177,"Wassertemperaturgrenze zur Auswahl temperaturabhängiger Abtaustufen. Gehört zur Umschaltung der Abtaufrequenz; keine normale Heizsolltemperatur. Die genaue Zuordnung der Stufen ist nicht erläutert.","Water-temperature threshold for selecting temperature-dependent defrost stages. Related to selecting defrost frequency, not a normal heating setpoint. The exact stage mapping is not explained.",source="Technisches Handbuch.pdf",pages=[178],level="partial")
add(178,"Verdichterfrequenz für die Abtaustufe bei hoher Wassertemperatur. Im Zusammenhang mit der temperaturabhängigen Stufenauswahl P177 zu beurteilen.","Compressor frequency for the high-water-temperature defrost stage. Interpret together with temperature-dependent stage selection P177.",source="Technisches Handbuch.pdf",pages=[178])

# Factory operating-point tables: retain their actual labels, without inventing
# outdoor temperatures for A/B/C/D/E or equating 35/55 to a live setpoint.
groups=[(184,'Verdichterfrequenz','compressor frequency','Hz'),(194,'Lüfterfrequenz','fan frequency','Hz'),
        (204,'Sollüberhitzung des Haupt-Expansionsventils','main expansion-valve target superheat','K'),
        (214,'Anfangsöffnung des Haupt-Expansionsventils','main expansion-valve initial opening','Schritte / steps'),
        (224,'Sollüberhitzung des Hilfs-Expansionsventils','auxiliary expansion-valve target superheat','K'),
        (234,'Anfangsöffnung des Hilfs-Expansionsventils','auxiliary expansion-valve initial opening','Schritte / steps')]
for start,de,en,unit in groups:
    for i in range(10):
        point=f"{35 if i<5 else 55}{'DCBAE'[i%5]}"
        add(start+i,f"Werkskennfeld: {de} am dokumentierten Betriebspunkt {point}. Das ist ein hinterlegter Kennfeldwert, nicht der aktuell gemessene Zustand. Die Unterlagen ordnen die Buchstaben nicht eindeutig konkreten Außenbedingungen zu; keine Heizkurvenstützstelle.",f"Factory operating-point table: {en} at documented point {point}. This is a stored table value, not a live measurement. The documents do not unambiguously map the letters to specific outdoor conditions; it is not a heating-curve point.",level="partial")
for n,temp in [(244,35),(245,55)]:
    add(n,f"Ziel-Wasserdurchfluss für die dokumentierte {temp}-Wassertemperatur-Betriebsbedingung, in L/min. Eine Kennfeldvorgabe und kein aktueller Durchflusswert. Wann die Firmware diesen Betriebspunkt verwendet, ist nicht näher erläutert.",f"Target water flow for the documented {temp} water-temperature operating condition, in L/min. A table setting rather than a live flow reading. The firmware's selection of this point is not explained further.",level="partial")
add(246,"Lüfterfrequenz unter der Nennbedingung mit niedriger Wassertemperatur. Gehört zum Werkskennfeld und ist kein allgemeiner Lüfter-Sollwert für jeden Betriebszustand.","Fan frequency at the low-water-temperature rated condition. Part of the factory operating-point table, not a universal fan setpoint for all operation.")
for n,temp in [(247,35),(249,55)]:
    add(n,f"Anfangsöffnung des elektronischen Haupt-Expansionsventils unter der {temp}-Nennbedingung, in Schritten. Kennfeldvorgabe für den Kältekreis; keine Pumpen- oder Wasser-Ventileinstellung.",f"Initial main electronic expansion-valve opening at the {temp} rated condition, in steps. Refrigerant-circuit table setting, not a pump or water-valve setting.")
add(248,"Dokumentationskonflikt: Excel bezeichnet dies als Hauptventilöffnung, das technische Handbuch nennt an derselben Adresse 0x01F8 die Lüfterfrequenz bei hoher Wassertemperatur (Hz). Die tatsächliche Funktion ist für die installierte Firmware offen.","Documentation conflict: the spreadsheet names a main-valve opening, while the technical manual identifies the same address 0x01F8 as high-water-temperature fan frequency (Hz). The actual function remains unverified for the installed firmware.",source="Technisches Handbuch.pdf",pages=[181],level="conflict")
for n,temp in [(250,35),(252,55)]:
    add(n,f"Sollüberhitzung des elektronischen Haupt-Expansionsventils unter der {temp}-Nennbedingung. Ein Kältekreis-Kennfeldwert; nicht die Wasserspreizung zwischen Vorlauf und Rücklauf.",f"Main electronic expansion-valve target superheat at the {temp} rated condition. A refrigerant-circuit table value, not the difference between supply and return water temperatures.")
for n,de,en in [(251,'Abschalten','disabling'),(253,'Einschalten','enabling')]:
    add(n,f"Stromschwelle zum {de} der Leistungsfaktorkorrektur (PFC) im Antrieb. Betrifft die Leistungselektronik, nicht einen Heizkreis. Der genaue Strommesspunkt und Ablauf sind nicht erläutert.",f"Current threshold for {en} power-factor correction (PFC) in the drive. Applies to power electronics, not a heating circuit. The exact current measurement point and sequence are not explained.",level="partial")
add(256,"Zeitbegrenzung für den Betrieb bei der entsprechenden Smart-Grid-/EVU-Signalkombination. Wirkt nur bei aktivierter SG-Funktion. Die Unterlagen nennen unterschiedliche Zeitangaben; die Darstellung ist keine Empfehlung zur Übernahme eines Handbuchdefaults.","Runtime limit under the corresponding Smart-Grid/EVU signal combination. Applies only when SG operation is enabled. Documents give conflicting time values; this explanation does not recommend applying a manual default.",source="Technisches Handbuch.pdf",pages=[91,181],level="conflict")
add(258,"Regelintervall des Mischventils für die zweite Temperaturzone. Bestimmt, wie oft die Regelung eine Ventilkorrektur vornehmen kann; nicht die vollständige Motorlaufzeit P259.","Control interval of the mixing valve for the second temperature zone. Determines how often control can adjust the valve; not the full actuator travel time P259.",source="Technisches Handbuch.pdf",pages=[90,181])
add(259,"Zeit für den vollständigen Stellweg des Mischventilantriebs. Muss zum verwendeten Antrieb passen; dient der zeitbasierten Positionssteuerung und ist kein Pumpennachlauf.","Time for the mixing-valve actuator's full travel. Must match the actuator; used for time-based position control, not pump postrun.",source="Technisches Handbuch.pdf",pages=[90,181])
add(260,"Obere prozentuale Ansteuerungsgrenze der internen DC-Wasserpumpe. Begrenzt deren Regelbereich; nicht die maximale Leistung der externen Zusatzpumpe.","Upper percentage control limit for the internal DC water pump. Limits its control range, not the maximum output of the external auxiliary pump.",source="Technisches Handbuch.pdf",pages=[155,181])
add(261,"Ansteuerung der internen Wasserpumpe bei konstant gehaltener Temperatur bzw. temperaturbedingter Bereitschaft. Ob die Pumpe in diesem Zustand läuft, hängt zusätzlich von der Pumpenbetriebsart ab. Kein dauerhafter Sollwert der Zusatzpumpe.","Internal water-pump output during constant-temperature operation or temperature-related standby. Whether the pump runs in that state also depends on its operating mode. Not a continuous setpoint for the auxiliary pump.",source="Technisches Handbuch.pdf",pages=[155,181])

missing = [code for code,r in records.items() if not (r.get('description') or r.get('description_de')) and code not in help_text]
assert not missing, missing
target = ROOT / "Documentation/system-parameter-help.json"
target.write_text(json.dumps({"schema":1,"notes":"Manual summaries; PDF pages are one-based. Defaults/ranges remain unchanged. No verified live firmware behaviour is implied by a matching register name.","parameters":help_text},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f"{len(help_text)} bilingual explanations written")
